window.ScripturaLexicons.LSJ.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n522\"><td class=\"greek\">ἁγιολόγος</td><td>LSJ</td><td>Adjetivo -ον: que fala de coisas sagradas, que profere palavras santas; leitura duvidosa em 1 Enoque 1.2.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n523\"><td class=\"greek\">ἁγιοποιέω</td><td>LSJ</td><td>Verbo: santificar, tornar sagrado; Fócio.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n524\"><td class=\"greek\">ἅγιος</td><td>LSJ</td><td>Adjetivo -α, -ον, alfa breve, relacionado ao culto divino. I. Sagrado, santo, consagrado aos deuses: templos, sacrifícios, pactos, juramentos; Heródoto, Platão, Xenofonte</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n525\"><td class=\"greek\">ἁγιότης</td><td>LSJ</td><td>Substantivo feminino, genitivo -ητος: santidade, consagração, equivalente a ἁγιωσύνη; LXX 2 Macabeus 15.2, Hebreus 12.10. Como título honorífico, papiro de Giessen 55.5.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n526\"><td class=\"greek\">ἁγισμός</td><td>LSJ</td><td>Substantivo masculino: oferenda ritual aos mortos, equivalente a ἐναγισμός; Diodoro Sículo 4.39.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n527\"><td class=\"greek\">ἁγιστεία</td><td>LSJ</td><td>Substantivo feminino: ritual ou serviço religioso, culto prestado aos deuses; no plural em Isócrates, Platão, Aristóteles, depois no singular em Estrabão, Josefo, Plutarc</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n528\"><td class=\"greek\">ἁγίστευμα</td><td>LSJ</td><td>Substantivo neutro: santuário, lugar consagrado; Procópio, De aedificiis 1.4.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n529\"><td class=\"greek\">ἁγιστεύω</td><td>LSJ</td><td>Verbo. I. Celebrar ou realizar ritos sagrados; com acusativo ἱερουργίαν, de cerimônia ritual; no passivo, ritos realizados, Platão, Dionísio de Halicarnasso, Fílon. II. S</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n530\"><td class=\"greek\">ἁγιστήριον</td><td>LSJ</td><td>Substantivo neutro: recipiente ou fonte para aspersão ritual, περιρραντήριον; inscrição de Pérgamo 255.9, plural.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n531\"><td class=\"greek\">ἁγιστός</td><td>LSJ</td><td>Adjetivo -ή, -όν: santificado, consagrado; Etymologicum Gudianum, no verbete ἁγιστεία.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n532\"><td class=\"greek\">ἁγιστύς</td><td>LSJ</td><td>Substantivo feminino, genitivo -ύος: cerimônia religiosa, rito; Calímaco, Aitia 1.1.3, fr. 178.3 Pf.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n533\"><td class=\"greek\">ἁγιώδως</td><td>LSJ</td><td>Advérbio: de modo sagrado, santamente; superlativo ἁγιωδέστατα com leitura duvidosa em Fílon 1.675.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n534\"><td class=\"greek\">ἁγιωσύνη</td><td>LSJ</td><td>Substantivo feminino: santidade, qualidade sagrada; LXX 2 Macabeus 3.12, Romanos 1.4. Também forma de tratamento honorífico em papiro P.Meyer 24.2.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n535\"><td class=\"greek\">ἀγκ-</td><td>LSJ</td><td>Forma prefixal poética ἀγκ-, abreviatura de ἀνακ- em compostos de ἀνά; entrada morfológica, não substantivo.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n536\"><td class=\"greek\">ἀγκάζομαι</td><td>LSJ</td><td>Verbo médio épico, de ἀγκάς: erguer nos braços, tomar nos braços, carregar; cadáver levantado do chão, Ilíada 17.722; pedra levantada, Calímaco; Nono.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n537\"><td class=\"greek\">ἄγκαθεν</td><td>LSJ</td><td>Advérbio: nos braços, ἄγκαθεν λαβεῖν, pegar ao colo, Ésquilo, Eumênides 80. Também de apoiar-se nos cotovelos, Agamêmnon 3. Interpretação alternativa: contração de ἀνέκαθ</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n538\"><td class=\"greek\">ἀγκάλη</td><td>LSJ</td><td>Substantivo feminino, alfa breve. I. Braço dobrado, antebraço ou colo dos braços; frequentemente plural, receber, carregar e abraçar alguém, Ésquilo, Eurípides, Heródoto.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n539\"><td class=\"greek\">ἀγκαλιδαγωγέω</td><td>LSJ</td><td>Verbo: carregar um feixe ou braçada; Pausânias Gramático, fr. 90.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n540\"><td class=\"greek\">ἀγκαλιδαγωγός</td><td>LSJ</td><td>Adjetivo -όν: que carrega feixe ou braçada, especialmente animal de carga; de pessoas são usados ἀγκαλιδηφόρος e ἀγκαλιδηφορέω, Pólux 2.139 e 7.109.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n541\"><td class=\"greek\">ἀγκαλίδη</td><td>LSJ</td><td>Substantivo feminino: equivalente a ἀγκαλίς, braçada, colo; de uma mulher, inscrição de Amiso, Studia Pontica 3.6.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n542\"><td class=\"greek\">ἀγκαλίζομαι</td><td>LSJ</td><td>Verbo médio: abraçar, tomar nos braços, cercar de carinho, até de algo mau; Semônides, Antologia Palatina e Licófron; particípio passivo ἀγκαλιζόμενος em Esopo.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n543\"><td class=\"greek\">ἀγκαλῖναι</td><td>LSJ</td><td>Feminino plural: braços, abraço, colo; forma argiva equivalente a ἀγκάλαι, Hesíquio.</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n544\"><td class=\"greek\">ἀγκαλίς</td><td>LSJ</td><td>Substantivo feminino. I. No plural, braços, colo, também dativo plural épico ἀγκαλίδεσσιν; Ilíada e inscrições. II. Braçada de objetos, quantidade que os braços podem con</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n545\"><td class=\"greek\">ἀγκάλισμα</td><td>LSJ</td><td>Substantivo neutro, genitivo -ατος. I. Aquilo que se toma nos braços, objeto abraçado; por extensão, pessoa querida, predileta, Luciano e Licófron. II. Abraço, figuradame</td><td>LSJ</td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n546\"><td class=\"greek\">ἀγκαλισμός</td><td>LSJ</td><td>Substantivo masculino: operação de reunir em braçadas ou formar feixes; papiro de Oxirrinco 1631.9, século III d.C.</td><td>LSJ</td></tr>\n";
window.ScripturaLexicons.LSJ.cardsHtml+="<article id=\"entry-lsj-n522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n522\" data-lsj-ordinal=\"526\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιολόγος\" data-meanings=\"Adjetivo -ον: que fala de coisas sagradas, que profere palavras santas; leitura duvidosa em 1 Enoque 1.2.\">ἁγιολόγος</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Adjetivo -ον: que fala de coisas sagradas, que profere palavras santas; leitura duvidosa em 1 Enoque 1.2.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p></p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(giolo/gos&quot; orig_id=&quot;n522&quot; key=&quot;a(giolo/gos&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγιο-λόγος&quot;&gt;ἁγιολόγος&lt;/head&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ον&lt;/itype&gt;, &lt;sense id=&quot;n522.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;speaking holy things,&lt;/i&gt; dub. in &lt;title&gt;I Enoch&lt;/title&gt; 1.2.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n523\" data-lsj-ordinal=\"527\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιοποιέω\" data-meanings=\"Verbo: santificar, tornar sagrado; Fócio.\">ἁγιοποιέω</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Verbo: santificar, tornar sagrado; Fócio.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p></p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(giopoie/w&quot; orig_id=&quot;n523&quot; key=&quot;a(giopoie/w&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγιο-ποιέω&quot;&gt;ἁγιοποιέω&lt;/head&gt;, &lt;sense id=&quot;n523.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;sanctify,&lt;/i&gt; &lt;author&gt;Phot.&lt;/author&gt;&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n524\" data-lsj-ordinal=\"528\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιος\" data-meanings=\"Adjetivo -α, -ον, alfa breve, relacionado ao culto divino. I. Sagrado, santo, consagrado aos deuses: templos, sacrifícios, pactos, juramentos; He\">ἅγιος</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Adjetivo -α, -ον, alfa breve, relacionado ao culto divino. I. Sagrado, santo, consagrado aos deuses: templos, sacrifícios, pactos, juramentos; Heródoto, Platão, Xenofonte. Substantivado τὸ ἅγιον, templo, santuário, LXX Êxodo 26.33 e Hebreus 9.2; τὰ ἅγια τῶν ἁγίων, Santo dos Santos, 3 Reis 8.6, Hebreus 9.3. II. De pessoas, santo, puro: λαὸς ἅγιος Κυρίῳ, povo santo ao Senhor, Deuteronômio 7.6; οἱ ἅγιοι, os santos, 1 Coríntios 6.1; πνεῦμα ἅγιον, Espírito Santo, Mateus 3.11. Advérbio ἁγίως, santamente. III. Em sentido desfavorável, maldito, execrável, Cratino, Eustácio. Não ocorre em Homero, Hesíodo ou trágicos, que empregam ἁγνός; etimologia com sânscrito yajati é possível, não certa.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Hdt. 2.41 · 44 · Pl. Criti. 116c · X. HG 3.2.19 · Antiph. 147.7 · Luc. Syr.D. 13 · Isoc. 10.63 · Pl. Lg. 729e · Id. Cri. 51a · Arist. Mir. 834b11 · LXX Ex. 26.33 · Ep.Hebr. 9.2 · 3 Ki. 8.6 · Ep.Hebr. 9.3 · Ar. Av. 522 · LXX De. 7.6 · 1 Ep.Cor. 6.1 · Ev.Matt. 3.11 · Isoc. 11.25 · Cratin. 373 · Eust. 1356.59</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(/gios&quot; orig_id=&quot;n524&quot; key=&quot;a(/gios&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἅγιος&quot;&gt;ἅγιος&lt;/head&gt; &lt;pron extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot;&gt;[ᾰ]&lt;/pron&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;α&lt;/itype&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ον&lt;/itype&gt;, &lt;sense id=&quot;n524.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;devoted to the gods:&lt;/i&gt; &lt;/sense&gt;&lt;sense n=&quot;I&quot; id=&quot;n524.1&quot; level=&quot;2&quot; opt=&quot;n&quot;&gt; in good sense, &lt;i&gt;sacred, holy:&lt;/i&gt; &lt;/sense&gt;&lt;sense n=&quot;1&quot; id=&quot;n524.2&quot; level=&quot;3&quot; opt=&quot;n&quot;&gt; of things, esp. temples, &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;Ἀφροδίτης ἱρὸν ἅ.&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0016,001:2:41&quot;&gt;&lt;author&gt;Hdt.&lt;/author&gt; 2.41&lt;/bibl&gt;&lt;/cit&gt;; &lt;foreign lang=&quot;grc&quot;&gt;ἱρὸν Ἡρακλέος ἅ.&lt;/foreign&gt; ib. &lt;bibl n=&quot;Perseus:abo:tlg,0016,001:2:44&quot;&gt;44&lt;/bibl&gt;, cf. &lt;bibl n=&quot;Perseus:abo:tlg,0059,032:116c&quot;&gt;&lt;author&gt;Pl.&lt;/author&gt; &lt;title&gt;Criti.&lt;/title&gt; 116c&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0032,001:3:2:19&quot;&gt;&lt;author&gt;X.&lt;/author&gt; &lt;title&gt;HG&lt;/title&gt; 3.2.19&lt;/bibl&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;θηρίον&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0410,001:147:7&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Antiph.&lt;/author&gt; 147.7&lt;/bibl&gt;&lt;/cit&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;νηὸν ἐπὶ τῷ χάσματι Ἥρης ἅ. ἐστήσατο&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0062,041:13&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Luc.&lt;/author&gt; &lt;title&gt;Syr.D.&lt;/title&gt; 13&lt;/bibl&gt;&lt;/cit&gt;: generally, &lt;foreign lang=&quot;grc&quot;&gt;θυσίαι, ξυμβόλαια,&lt;/foreign&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0010,009:63&quot;&gt;&lt;author&gt;Isoc.&lt;/author&gt; 10.63&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0059,034:729e&quot;&gt;&lt;author&gt;Pl.&lt;/author&gt; &lt;title&gt;Lg.&lt;/title&gt; 729e&lt;/bibl&gt; (&lt;gramGrp opt=&quot;n&quot;&gt;&lt;gram type=&quot;comp&quot; opt=&quot;n&quot;&gt;Sup.&lt;/gram&gt;&lt;/gramGrp&gt;); &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;μητρός.. ἐστι πατρὶς ἁγιώτερον&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0059,003:51a&quot;&gt;&lt;author&gt;Id.&lt;/author&gt; &lt;title&gt;Cri.&lt;/title&gt; 51a&lt;/bibl&gt;&lt;/cit&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ὅρκος ἅ.&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0086,027:834b:11&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Arist.&lt;/author&gt; &lt;title&gt;Mir.&lt;/title&gt; 834b11&lt;/bibl&gt;&lt;/cit&gt;; &lt;orth lang=&quot;grc&quot;&gt;ἅγιον&lt;/orth&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;τό&lt;/gen&gt;, &lt;i&gt;temple,&lt;/i&gt; &lt;title&gt;OGI&lt;/title&gt; 56.59 (&lt;placeName&gt;Canopus&lt;/placeName&gt;), &lt;bibl n=&quot;Perseus:abo:tlg,0527,002:26:33&quot;&gt;&lt;author&gt;LXX&lt;/author&gt; &lt;title&gt;Ex.&lt;/title&gt; 26.33&lt;/bibl&gt;, al., cf. &lt;bibl n=&quot;Perseus:abo:tlg,0031,019:9:2&quot;&gt;&lt;title&gt;Ep.Hebr.&lt;/title&gt; 9.2&lt;/bibl&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;τὸ ἅ. τῶν ἁγίων&lt;/quote&gt; &lt;i&gt;Holy of Holies,&lt;/i&gt; &lt;author&gt;LXX&lt;/author&gt;&lt;/cit&gt; l.c.; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;τὰ ἅ. τῶν ἁ.&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0527,013:8:6&quot;&gt;&lt;title&gt;3 Ki.&lt;/title&gt; 8.6&lt;/bibl&gt;&lt;/cit&gt;, etc., cf. &lt;bibl n=&quot;Perseus:abo:tlg,0031,019:9:3&quot;&gt;&lt;title&gt;Ep.Hebr.&lt;/title&gt; 9.3&lt;/bibl&gt;. &lt;/sense&gt;&lt;sense n=&quot;2&quot; id=&quot;n524.3&quot; level=&quot;3&quot; opt=&quot;n&quot;&gt; of persons, &lt;i&gt;holy, pure,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0019,006:522&quot;&gt;&lt;author&gt;Ar.&lt;/author&gt; &lt;title&gt;Av.&lt;/title&gt; 522&lt;/bibl&gt; (anap.); &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;λαὸς ἅ. Κυρίῳ&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0527,005:7:6&quot;&gt;&lt;author&gt;LXX&lt;/author&gt; &lt;title&gt;De.&lt;/title&gt; 7.6&lt;/bibl&gt;&lt;/cit&gt;, al.; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;οἱ ἅ.&lt;/quote&gt; &lt;i&gt;the Saints,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0031,007:6:1&quot;&gt;&lt;title&gt;1 Ep.Cor.&lt;/title&gt; 6.1&lt;/bibl&gt;&lt;/cit&gt;, al.; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;πνεῦμα ἅ.&lt;/quote&gt; &lt;i&gt;the Holy Spirit,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0031,001:3:11&quot;&gt;&lt;title&gt;Ev.Matt.&lt;/title&gt; 3.11&lt;/bibl&gt;&lt;/cit&gt;, al. &lt;pos opt=&quot;n&quot;&gt;Adv.&lt;/pos&gt; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ἁγίως καὶ σεμνῶς ἔχειν&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0010,010:25&quot;&gt;&lt;author&gt;Isoc.&lt;/author&gt; 11.25&lt;/bibl&gt;&lt;/cit&gt;. &lt;/sense&gt;&lt;sense n=&quot;II&quot; id=&quot;n524.4&quot; level=&quot;2&quot; opt=&quot;n&quot;&gt; in bad sense, &lt;i&gt;accursed, execrable,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0434,001:373&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Cratin.&lt;/author&gt; 373&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,4083,001:1356:59&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Eust.&lt;/author&gt; 1356.59&lt;/bibl&gt;.—Never in &lt;author&gt;Hom.&lt;/author&gt;, &lt;author&gt;Hes.&lt;/author&gt;, or Trag. (who use &lt;foreign lang=&quot;grc&quot;&gt;ἁγνός&lt;/foreign&gt;); rare in &lt;gramGrp opt=&quot;n&quot;&gt;&lt;gram type=&quot;dialect&quot; opt=&quot;n&quot;&gt;Att.&lt;/gram&gt;&lt;/gramGrp&gt; (v. supr.). (Possibly cognate with Skt. &lt;foreign lang=&quot;sa&quot;&gt;yajati&lt;/foreign&gt; ‘sacrifice’.)&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n525\" data-lsj-ordinal=\"529\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιότης\" data-meanings=\"Substantivo feminino, genitivo -ητος: santidade, consagração, equivalente a ἁγιωσύνη; LXX 2 Macabeus 15.2, Hebreus 12.10. Como título honorífico,\">ἁγιότης</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo feminino, genitivo -ητος: santidade, consagração, equivalente a ἁγιωσύνη; LXX 2 Macabeus 15.2, Hebreus 12.10. Como título honorífico, papiro de Giessen 55.5.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>LXX 2 Ma. 15.2 · Ep.Hebr. 12.10 · PGiss. 55.5</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(gio/ths&quot; orig_id=&quot;n525&quot; key=&quot;a(gio/ths&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγιότης&quot;&gt;ἁγιότης&lt;/head&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ητος&lt;/itype&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἡ&lt;/gen&gt;, &lt;sense id=&quot;n525.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;= ἁγιωσύνη, &lt;bibl n=&quot;Perseus:abo:tlg,0527,024:15:2&quot;&gt;&lt;author&gt;LXX&lt;/author&gt; &lt;title&gt;2 Ma.&lt;/title&gt; 15.2&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0031,019:12:10&quot;&gt;&lt;title&gt;Ep.Hebr.&lt;/title&gt; 12.10&lt;/bibl&gt;. &lt;/sense&gt;&lt;sense n=&quot;II&quot; id=&quot;n525.1&quot; level=&quot;2&quot; opt=&quot;n&quot;&gt; as title, &lt;bibl n=&quot;Perseus:abo:pap,P.Giss.:55:5&quot; default=&quot;NO&quot;&gt;&lt;title&gt;PGiss.&lt;/title&gt; 55.5&lt;/bibl&gt; &lt;date&gt;(vi A. D.)&lt;/date&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n526\" data-lsj-ordinal=\"530\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγισμός\" data-meanings=\"Substantivo masculino: oferenda ritual aos mortos, equivalente a ἐναγισμός; Diodoro Sículo 4.39.\">ἁγισμός</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo masculino: oferenda ritual aos mortos, equivalente a ἐναγισμός; Diodoro Sículo 4.39.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>D.S. 4.39</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(gismo/s&quot; orig_id=&quot;n526&quot; key=&quot;a(gismo/s&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγ-ισμός&quot;&gt;ἁγισμός&lt;/head&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;οῦ&lt;/itype&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ὁ&lt;/gen&gt;, &lt;sense id=&quot;n526.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;= ἐναγισμός, &lt;i&gt;offering to the dead,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0060,001:4:39&quot;&gt;&lt;author&gt;D.S.&lt;/author&gt; 4.39&lt;/bibl&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n527\" data-lsj-ordinal=\"531\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιστεία\" data-meanings=\"Substantivo feminino: ritual ou serviço religioso, culto prestado aos deuses; no plural em Isócrates, Platão, Aristóteles, depois no singular em \">ἁγιστεία</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo feminino: ritual ou serviço religioso, culto prestado aos deuses; no plural em Isócrates, Platão, Aristóteles, depois no singular em Estrabão, Josefo, Plutarco e Juliano.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Isoc. 11.28 · Pl. Ax. 371d · Arist. Cael. 268a14 · Str. 9.3.7 · J. Ap. 1.7 · Plu. Rom. 22 · Jul. Or. 5.178d</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(gistei/a&quot; orig_id=&quot;n527&quot; key=&quot;a(gistei/a&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγ-ιστεία&quot;&gt;ἁγιστεία&lt;/head&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἡ&lt;/gen&gt;, &lt;sense id=&quot;n527.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;ritual, service,&lt;/i&gt; &lt;foreign lang=&quot;grc&quot;&gt;τῶν θεῶν,&lt;/foreign&gt; in pl., &lt;bibl n=&quot;Perseus:abo:tlg,0010,010:28&quot;&gt;&lt;author&gt;Isoc.&lt;/author&gt; 11.28&lt;/bibl&gt;, cf. &lt;bibl n=&quot;Perseus:abo:tlg,0059,038:371d&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Pl.&lt;/author&gt; &lt;title&gt;Ax.&lt;/title&gt; 371d&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0086,005:268a:14&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Arist.&lt;/author&gt; &lt;title&gt;Cael.&lt;/title&gt; 268a14&lt;/bibl&gt;; later in sg., &lt;bibl n=&quot;Perseus:abo:tlg,0099,001:9:3:7&quot;&gt;&lt;author&gt;Str.&lt;/author&gt; 9.3.7&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0526,003:1:7&quot;&gt;&lt;author&gt;J.&lt;/author&gt; &lt;title&gt;Ap.&lt;/title&gt; 1.7&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0007,002:22&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Plu.&lt;/author&gt; &lt;title&gt;Rom.&lt;/title&gt; 22&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,2003,001:5:178d&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Jul.&lt;/author&gt; &lt;title&gt;Or.&lt;/title&gt; 5.178d&lt;/bibl&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n528\" data-lsj-ordinal=\"532\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγίστευμα\" data-meanings=\"Substantivo neutro: santuário, lugar consagrado; Procópio, De aedificiis 1.4.\">ἁγίστευμα</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo neutro: santuário, lugar consagrado; Procópio, De aedificiis 1.4.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Procop. Aed. 1.4</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(gi/steuma&quot; orig_id=&quot;n528&quot; key=&quot;a(gi/steuma&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγ-ίστευμα&quot;&gt;ἁγίστευμα&lt;/head&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;τό&lt;/gen&gt;, &lt;sense id=&quot;n528.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;sanctuary,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,4029,003:1:4&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Procop.&lt;/author&gt; &lt;title&gt;Aed.&lt;/title&gt; 1.4&lt;/bibl&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n529\" data-lsj-ordinal=\"533\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιστεύω\" data-meanings=\"Verbo. I. Celebrar ou realizar ritos sagrados; com acusativo ἱερουργίαν, de cerimônia ritual; no passivo, ritos realizados, Platão, Dionísio de H\">ἁγιστεύω</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Verbo. I. Celebrar ou realizar ritos sagrados; com acusativo ἱερουργίαν, de cerimônia ritual; no passivo, ritos realizados, Platão, Dionísio de Halicarnasso, Fílon. II. Ser santo, viver com pureza, reverenciar a alma, Eurípides, Bacantes 74; lugar sagrado em Pausânias. III. Ativamente purificar, especialmente mãos manchadas de homicídio, oráculo apud Pausânias 10.6.7. IV. Considerar santo, especialmente locais no passivo, Estrabão.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Pl. Lg. 759d · D.H. 1.40 · Ph. 2.231 · E. Ba. 74 · Paus. 6.20.2 · 8.13.1 · Paus. 10.6.7 · Str. 9.3.1</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(gisteu/w&quot; orig_id=&quot;n529&quot; key=&quot;a(gisteu/w&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγ-ιστεύω&quot;&gt;ἁγιστεύω&lt;/head&gt;, &lt;sense id=&quot;n529.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;perform sacred rites,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0059,034:759d&quot;&gt;&lt;author&gt;Pl.&lt;/author&gt; &lt;title&gt;Lg.&lt;/title&gt; 759d&lt;/bibl&gt;: c. acc., &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ἱερουργίαν&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0081,001:1:40&quot; default=&quot;NO&quot;&gt;&lt;author&gt;D.H.&lt;/author&gt; 1.40&lt;/bibl&gt;&lt;/cit&gt;:—&lt;gramGrp opt=&quot;n&quot;&gt;&lt;gram type=&quot;voice&quot; opt=&quot;n&quot;&gt;Pass.&lt;/gram&gt;&lt;/gramGrp&gt;, &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ὅσα ἄλλα -εύεται&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0018,001:2:231&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Ph.&lt;/author&gt; 2.231&lt;/bibl&gt;&lt;/cit&gt;. &lt;/sense&gt;&lt;sense n=&quot;2&quot; id=&quot;n529.1&quot; level=&quot;3&quot; opt=&quot;n&quot;&gt; &lt;i&gt;to be holy, live purely,&lt;/i&gt; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ὅστις.. βιοτὰν ἁ. καὶ θιασεύεται ψυχάν&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0006,017:74&quot;&gt;&lt;author&gt;E.&lt;/author&gt; &lt;title&gt;Ba.&lt;/title&gt; 74&lt;/bibl&gt;&lt;/cit&gt;; &lt;i&gt;to be sacred,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0525,001:6:20:2&quot;&gt;&lt;author&gt;Paus.&lt;/author&gt; 6.20.2&lt;/bibl&gt;, cf. &lt;bibl n=&quot;Perseus:abo:tlg,0525,001:8:13:1&quot;&gt;8.13.1&lt;/bibl&gt;. &lt;/sense&gt;&lt;sense n=&quot;II&quot; id=&quot;n529.2&quot; level=&quot;2&quot; opt=&quot;n&quot;&gt; &lt;gramGrp opt=&quot;n&quot;&gt;&lt;gram type=&quot;voice&quot; opt=&quot;n&quot;&gt;Act.&lt;/gram&gt;&lt;/gramGrp&gt;, &lt;i&gt;purify,&lt;/i&gt; &lt;foreign lang=&quot;grc&quot;&gt;φόνου χεῖρας&lt;/foreign&gt; Orac. ap. &lt;bibl n=&quot;Perseus:abo:tlg,0525,001:10:6:7&quot;&gt;&lt;author&gt;Paus.&lt;/author&gt; 10.6.7&lt;/bibl&gt;. &lt;/sense&gt;&lt;sense n=&quot;2&quot; id=&quot;n529.3&quot; level=&quot;3&quot; opt=&quot;n&quot;&gt; &lt;i&gt;deem holy:&lt;/i&gt;—&lt;gramGrp opt=&quot;n&quot;&gt;&lt;gram type=&quot;voice&quot; opt=&quot;n&quot;&gt;Pass.&lt;/gram&gt;&lt;/gramGrp&gt;, of places, &lt;bibl n=&quot;Perseus:abo:tlg,0099,001:9:3:1&quot;&gt;&lt;author&gt;Str.&lt;/author&gt; 9.3.1&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0081,001:1:40&quot; default=&quot;NO&quot;&gt;&lt;author&gt;D.H.&lt;/author&gt; 1.40&lt;/bibl&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n530\" data-lsj-ordinal=\"534\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιστήριον\" data-meanings=\"Substantivo neutro: recipiente ou fonte para aspersão ritual, περιρραντήριον; inscrição de Pérgamo 255.9, plural.\">ἁγιστήριον</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo neutro: recipiente ou fonte para aspersão ritual, περιρραντήριον; inscrição de Pérgamo 255.9, plural.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p></p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(gisth/rion&quot; orig_id=&quot;n530&quot; key=&quot;a(gisth/rion&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγ-ιστήριον&quot;&gt;ἁγιστήριον&lt;/head&gt;, τό, &lt;sense id=&quot;n530.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;= περιρραντήριον, &lt;title&gt;Inscr.Perg.&lt;/title&gt; 255.9 (pl.).&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n531\" data-lsj-ordinal=\"535\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιστός\" data-meanings=\"Adjetivo -ή, -όν: santificado, consagrado; Etymologicum Gudianum, no verbete ἁγιστεία.\">ἁγιστός</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Adjetivo -ή, -όν: santificado, consagrado; Etymologicum Gudianum, no verbete ἁγιστεία.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p></p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(gisto/s&quot; orig_id=&quot;n531&quot; key=&quot;a(gisto/s&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγ-ιστός&quot;&gt;ἁγιστός&lt;/head&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ή&lt;/itype&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;όν&lt;/itype&gt;, &lt;sense id=&quot;n531.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;hallowed,&lt;/i&gt; &lt;title&gt;Et.Gud.&lt;/title&gt; s.v. ἁγιστεία.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n532\" data-lsj-ordinal=\"536\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιστύς\" data-meanings=\"Substantivo feminino, genitivo -ύος: cerimônia religiosa, rito; Calímaco, Aitia 1.1.3, fr. 178.3 Pf.\">ἁγιστύς</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo feminino, genitivo -ύος: cerimônia religiosa, rito; Calímaco, Aitia 1.1.3, fr. 178.3 Pf.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Call. Aet. 1.1.3</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(gistu/s&quot; orig_id=&quot;n532&quot; key=&quot;a(gistu/s&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγ-ιστύς&quot;&gt;ἁγιστύς&lt;/head&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ύος&lt;/itype&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἡ&lt;/gen&gt;, &lt;sense id=&quot;n532.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;ceremony,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0533,006:178:3&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Call.&lt;/author&gt; &lt;title&gt;Aet.&lt;/title&gt; 1.1.3&lt;/bibl&gt; [Fr. 178.3 Pf.].&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n533\" data-lsj-ordinal=\"537\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιώδως\" data-meanings=\"Advérbio: de modo sagrado, santamente; superlativo ἁγιωδέστατα com leitura duvidosa em Fílon 1.675.\">ἁγιώδως</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Advérbio: de modo sagrado, santamente; superlativo ἁγιωδέστατα com leitura duvidosa em Fílon 1.675.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Ph. 1.675</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(giw/dws&quot; orig_id=&quot;n533&quot; key=&quot;a(giw/dws&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγιώδως&quot;&gt;ἁγιώδως&lt;/head&gt;, &lt;pos opt=&quot;n&quot;&gt;Adv.&lt;/pos&gt; &lt;sense id=&quot;n533.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;in sacred manner:&lt;/i&gt; &lt;gramGrp opt=&quot;n&quot;&gt;&lt;gram type=&quot;comp&quot; opt=&quot;n&quot;&gt;Sup.&lt;/gram&gt;&lt;/gramGrp&gt; &lt;foreign lang=&quot;grc&quot;&gt;-έστατα&lt;/foreign&gt; dub. in &lt;bibl n=&quot;Perseus:abo:tlg,0018,001:1:675&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Ph.&lt;/author&gt; 1.675&lt;/bibl&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n534\" data-lsj-ordinal=\"538\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιωσύνη\" data-meanings=\"Substantivo feminino: santidade, qualidade sagrada; LXX 2 Macabeus 3.12, Romanos 1.4. Também forma de tratamento honorífico em papiro P.Meyer 24.\">ἁγιωσύνη</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo feminino: santidade, qualidade sagrada; LXX 2 Macabeus 3.12, Romanos 1.4. Também forma de tratamento honorífico em papiro P.Meyer 24.2.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>LXX 2 Ma. 3.12 · Ep.Rom. 1.4 · PMeyer 24.2</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa(giwsu/nh&quot; orig_id=&quot;n534&quot; key=&quot;a(giwsu/nh&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἁγιωσύνη&quot;&gt;ἁγιωσύνη&lt;/head&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἡ&lt;/gen&gt;, &lt;sense id=&quot;n534.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;holiness, sanctity,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0527,024:3:12&quot;&gt;&lt;author&gt;LXX&lt;/author&gt; &lt;title&gt;2 Ma.&lt;/title&gt; 3.12&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0031,006:1:4&quot;&gt;&lt;title&gt;Ep.Rom.&lt;/title&gt; 1.4&lt;/bibl&gt;, etc. &lt;/sense&gt;&lt;sense n=&quot;II&quot; id=&quot;n534.1&quot; level=&quot;2&quot; opt=&quot;n&quot;&gt; as title, &lt;bibl n=&quot;Perseus:abo:pap,P.Meyer:24:2&quot; default=&quot;NO&quot;&gt;&lt;title&gt;PMeyer&lt;/title&gt; 24.2&lt;/bibl&gt; &lt;date&gt;(vi A. D.)&lt;/date&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n535\" data-lsj-ordinal=\"539\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκ-\" data-meanings=\"Forma prefixal poética ἀγκ-, abreviatura de ἀνακ- em compostos de ἀνά; entrada morfológica, não substantivo.\">ἀγκ-</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Forma prefixal poética ἀγκ-, abreviatura de ἀνακ- em compostos de ἀνά; entrada morfológica, não substantivo.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p></p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gk&quot; orig_id=&quot;n535&quot; key=&quot;a)gk&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;pref&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκ-&quot;&gt;ἀγκ-&lt;/head&gt;, Poet. abbrev. for &lt;foreign lang=&quot;grc&quot;&gt;ἀνακ-&lt;/foreign&gt; in compds. of &lt;foreign lang=&quot;grc&quot;&gt;ἀνά.&lt;/foreign&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n536\" data-lsj-ordinal=\"540\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκάζομαι\" data-meanings=\"Verbo médio épico, de ἀγκάς: erguer nos braços, tomar nos braços, carregar; cadáver levantado do chão, Ilíada 17.722; pedra levantada, Calímaco; \">ἀγκάζομαι</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Verbo médio épico, de ἀγκάς: erguer nos braços, tomar nos braços, carregar; cadáver levantado do chão, Ilíada 17.722; pedra levantada, Calímaco; Nono.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Il. 17.722 · Call. Hec. 21.1 · Nonn. D. 7.318</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gka/zomai&quot; orig_id=&quot;n536&quot; key=&quot;a)gka/zomai&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκάζομαι&quot;&gt;ἀγκάζομαι&lt;/head&gt;, (&lt;etym lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἀγκάς&lt;/etym&gt;) &lt;gramGrp opt=&quot;n&quot;&gt;&lt;gram type=&quot;dialect&quot; opt=&quot;n&quot;&gt;Ep.&lt;/gram&gt;&lt;/gramGrp&gt;, &lt;sense id=&quot;n536.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;lift up in the arms,&lt;/i&gt; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;νεκρὸν ἀπὸ χθονὸς ἀγκάζοντο&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0012,001:17:722&quot;&gt;&lt;title&gt;Il.&lt;/title&gt; 17.722&lt;/bibl&gt;&lt;/cit&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;λίθον ἀγκάσσασθαι&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0533,009:236:1&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Call.&lt;/author&gt; &lt;title&gt;Hec.&lt;/title&gt; 21.1&lt;/bibl&gt; [Fr. 236.1 Pf.]&lt;/cit&gt;, cf. &lt;bibl n=&quot;Perseus:abo:tlg,2045,001:7:318&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Nonn.&lt;/author&gt; &lt;title&gt;D.&lt;/title&gt; 7.318&lt;/bibl&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n537\" data-lsj-ordinal=\"541\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγκαθεν\" data-meanings=\"Advérbio: nos braços, ἄγκαθεν λαβεῖν, pegar ao colo, Ésquilo, Eumênides 80. Também de apoiar-se nos cotovelos, Agamêmnon 3. Interpretação alterna\">ἄγκαθεν</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Advérbio: nos braços, ἄγκαθεν λαβεῖν, pegar ao colo, Ésquilo, Eumênides 80. Também de apoiar-se nos cotovelos, Agamêmnon 3. Interpretação alternativa: contração de ἀνέκαθεν, «de cima», conforme escólios e Hesíquio.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>A. Eu. 80 · A. Ag. 3</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)/gka^qen&quot; orig_id=&quot;n537&quot; key=&quot;a)/gka^qen&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἄγκᾰθεν&quot;&gt;ἄγκαθεν&lt;/head&gt;, &lt;pos opt=&quot;n&quot;&gt;Adv.&lt;/pos&gt; &lt;sense id=&quot;n537.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;in the arms,&lt;/i&gt; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ἄ. λαβεῖν τι&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0085,007:80&quot;&gt;&lt;author&gt;A.&lt;/author&gt; &lt;title&gt;Eu.&lt;/title&gt; 80&lt;/bibl&gt;&lt;/cit&gt;. &lt;/sense&gt;&lt;sense n=&quot;2&quot; id=&quot;n537.1&quot; level=&quot;3&quot; opt=&quot;n&quot;&gt; &lt;i&gt;resting on the elbows,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0085,005:3&quot;&gt;&lt;author&gt;A.&lt;/author&gt; &lt;title&gt;Ag.&lt;/title&gt; 3&lt;/bibl&gt;; also expl. as &lt;gramGrp opt=&quot;n&quot;&gt;&lt;gram type=&quot;var&quot; opt=&quot;n&quot;&gt;contr.&lt;/gram&gt;&lt;/gramGrp&gt; for &lt;foreign lang=&quot;grc&quot;&gt;ἀνέκαθεν,&lt;/foreign&gt; = ἄνωθεν, &lt;i&gt;on the top,&lt;/i&gt; cf. Sch. ad l.c., &lt;author&gt;Hsch.&lt;/author&gt;, &lt;title&gt;AB&lt;/title&gt; 337.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n538\" data-lsj-ordinal=\"542\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκάλη\" data-meanings=\"Substantivo feminino, alfa breve. I. Braço dobrado, antebraço ou colo dos braços; frequentemente plural, receber, carregar e abraçar alguém, Ésqu\">ἀγκάλη</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo feminino, alfa breve. I. Braço dobrado, antebraço ou colo dos braços; frequentemente plural, receber, carregar e abraçar alguém, Ésquilo, Eurípides, Heródoto. II. Dobra do joelho, Célio Aureliano. III. Metaforicamente, algo que envolve estreitamente, como abraço das ondas, rochedo, mar ou ar; Arquíloco e Ésquilo. IV. Braçada, feixe, molho, em papiros BGU, Londres e Oxirrinco.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>A. Ag. 723 · Supp. 481 · E. Alc. 351 · X. Cyr. 7.5.50 · E. IT 289 · Or. 464 · Id. Ion 761 · IT 1250 · Ion 1598 · 962 · Id. Andr. 747 · Corinn. 19 · Hdt. 6.61 · Timocl. 7.4 · Archil. 23 · A. Pr. 1019 · Id. Ch. 587 · E. Or. 1378 · Nausicr. 1.3 · E. Fr. 941 · BGU 1180 · PLond. 1.131r396 · POxy. 935.19</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gka/lh&quot; orig_id=&quot;n538&quot; key=&quot;a)gka/lh&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκάλη&quot;&gt;ἀγκάλη&lt;/head&gt; &lt;pron extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot;&gt;[ᾰ]&lt;/pron&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἡ&lt;/gen&gt;, &lt;sense id=&quot;n538.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;bent arm,&lt;/i&gt; mostly in pl., &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ἐν ἀγκάλαις&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0085,005:723&quot;&gt;&lt;author&gt;A.&lt;/author&gt; &lt;title&gt;Ag.&lt;/title&gt; 723&lt;/bibl&gt;&lt;/cit&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0085,001:481&quot;&gt;&lt;title&gt;Supp.&lt;/title&gt; 481&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0006,002:351&quot;&gt;&lt;author&gt;E.&lt;/author&gt; &lt;title&gt;Alc.&lt;/title&gt; 351&lt;/bibl&gt;, al.; prov., &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ἐν ταῖς ἀ. περιΦέρειν τινά&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0032,007:7:5:50&quot;&gt;&lt;author&gt;X.&lt;/author&gt; &lt;title&gt;Cyr.&lt;/title&gt; 7.5.50&lt;/bibl&gt;&lt;/cit&gt;; without &lt;foreign lang=&quot;grc&quot;&gt;ἐν, ἀγκάλαις ἔχειν, περιΦέρειν,&lt;/foreign&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0006,013:289&quot;&gt;&lt;author&gt;E.&lt;/author&gt; &lt;title&gt;IT&lt;/title&gt; 289&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0006,016:464&quot;&gt;&lt;title&gt;Or.&lt;/title&gt; 464&lt;/bibl&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ἐπʼ ἀγκάλαις λαβεῖν&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0006,010:761&quot;&gt;&lt;author&gt;Id.&lt;/author&gt; &lt;title&gt;Ion&lt;/title&gt; 761&lt;/bibl&gt;&lt;/cit&gt;, cf. &lt;bibl n=&quot;Perseus:abo:tlg,0006,013:1250&quot;&gt;&lt;title&gt;IT&lt;/title&gt; 1250&lt;/bibl&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ἐς ἀ.&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0006,010:1598&quot;&gt;&lt;title&gt;Ion&lt;/title&gt; 1598&lt;/bibl&gt;&lt;/cit&gt;; &lt;foreign lang=&quot;grc&quot;&gt;πρὸς ἀγκάλαις πεσεῖν&lt;/foreign&gt; ib. &lt;bibl n=&quot;Perseus:abo:tlg,0006,010:962&quot;&gt;962&lt;/bibl&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ὑπʼ ἀγκάλαις σταθείς&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0006,006:747&quot;&gt;&lt;author&gt;Id.&lt;/author&gt; &lt;title&gt;Andr.&lt;/title&gt; 747&lt;/bibl&gt;&lt;/cit&gt;: rarely in sg., &lt;bibl n=&quot;Perseus:abo:tlg,0294,001:19&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Corinn.&lt;/author&gt; 19&lt;/bibl&gt; (s.v.l.); &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;φέρειν ἐν τῇ ἀ.&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0016,001:6:61&quot;&gt;&lt;author&gt;Hdt.&lt;/author&gt; 6.61&lt;/bibl&gt;&lt;/cit&gt;, cf. &lt;author&gt;X.&lt;/author&gt; l.c., &lt;bibl n=&quot;Perseus:abo:tlg,0515,001:7:4&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Timocl.&lt;/author&gt; 7.4&lt;/bibl&gt;. &lt;/sense&gt;&lt;sense n=&quot;2&quot; id=&quot;n538.1&quot; level=&quot;3&quot; opt=&quot;n&quot;&gt; &lt;i&gt;bend of knee,&lt;/i&gt; &lt;author&gt;Cael.Aur.&lt;/author&gt; &lt;title&gt;TP&lt;/title&gt; 5.1.2. &lt;/sense&gt;&lt;sense n=&quot;II&quot; id=&quot;n538.2&quot; level=&quot;2&quot; opt=&quot;n&quot;&gt; metaph., &lt;i&gt;anything closely enfolding,&lt;/i&gt; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;κυμάτων ἐν ἀγκάλαις&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0232,001:23&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Archil.&lt;/author&gt; 23&lt;/bibl&gt;&lt;/cit&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;πετραία ἀ.&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0085,003:1019&quot;&gt;&lt;author&gt;A.&lt;/author&gt; &lt;title&gt;Pr.&lt;/title&gt; 1019&lt;/bibl&gt;&lt;/cit&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;πόντιαι ἀ.&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0085,006:587&quot;&gt;&lt;author&gt;Id.&lt;/author&gt; &lt;title&gt;Ch.&lt;/title&gt; 587&lt;/bibl&gt;&lt;/cit&gt;, cf. &lt;bibl n=&quot;Perseus:abo:tlg,0006,016:1378&quot;&gt;&lt;author&gt;E.&lt;/author&gt; &lt;title&gt;Or.&lt;/title&gt; 1378&lt;/bibl&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;πελαγίοις ἐν ἀ.&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0478,001:1:3&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Nausicr.&lt;/author&gt; 1.3&lt;/bibl&gt;&lt;/cit&gt;; of the air, &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;γῆν..ἔχονθʼ ὑγραῖς ἐν ἀ.&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0006,020:941&quot; default=&quot;NO&quot;&gt;&lt;author&gt;E.&lt;/author&gt; &lt;title&gt;Fr.&lt;/title&gt; 941&lt;/bibl&gt;&lt;/cit&gt;. &lt;/sense&gt;&lt;sense n=&quot;III&quot; id=&quot;n538.3&quot; level=&quot;2&quot; opt=&quot;n&quot;&gt; &lt;i&gt;bundle, sheaf,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:pap,BGU:1180&quot; default=&quot;NO&quot;&gt;&lt;title&gt;BGU&lt;/title&gt; 1180&lt;/bibl&gt; &lt;date&gt;(i B. C.)&lt;/date&gt;, &lt;bibl n=&quot;Perseus:abo:pap,P.Lond.:1:131r396&quot; default=&quot;NO&quot;&gt;&lt;title&gt;PLond.&lt;/title&gt; 1.131r396&lt;/bibl&gt; &lt;date&gt;(i A. D.)&lt;/date&gt;, &lt;bibl n=&quot;Perseus:abo:pap,P.Oxy.:935:19&quot; default=&quot;NO&quot;&gt;&lt;title&gt;POxy.&lt;/title&gt; 935.19&lt;/bibl&gt; &lt;date&gt;(iii A. D.)&lt;/date&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n539\" data-lsj-ordinal=\"543\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκαλιδαγωγέω\" data-meanings=\"Verbo: carregar um feixe ou braçada; Pausânias Gramático, fr. 90.\">ἀγκαλιδαγωγέω</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Verbo: carregar um feixe ou braçada; Pausânias Gramático, fr. 90.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p></p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gka^li^dagwge/w&quot; orig_id=&quot;n539&quot; key=&quot;a)gka^li^dagwge/w&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκᾰλῐδ-αγωγέω&quot;&gt;ἀγκαλιδαγωγέω&lt;/head&gt;, &lt;sense id=&quot;n539.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;carry a bundle,&lt;/i&gt; &lt;author&gt;Paus.Gr.&lt;/author&gt; &lt;title&gt;Fr.&lt;/title&gt; 90.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n540\" data-lsj-ordinal=\"544\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκαλιδαγωγός\" data-meanings=\"Adjetivo -όν: que carrega feixe ou braçada, especialmente animal de carga; de pessoas são usados ἀγκαλιδηφόρος e ἀγκαλιδηφορέω, Pólux 2.139 e 7.1\">ἀγκαλιδαγωγός</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Adjetivo -όν: que carrega feixe ou braçada, especialmente animal de carga; de pessoas são usados ἀγκαλιδηφόρος e ἀγκαλιδηφορέω, Pólux 2.139 e 7.109.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Poll. 2.139 · 7.109</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gka^li^da^gwgo/s&quot; orig_id=&quot;n540&quot; key=&quot;a)gka^li^da^gwgo/s&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκᾰλῐδ-ᾰγωγός&quot;&gt;ἀγκαλιδαγωγός&lt;/head&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;όν&lt;/itype&gt;, &lt;sense id=&quot;n540.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;carrying an armful&lt;/i&gt; or &lt;i&gt;bundle,&lt;/i&gt; of beasts of burden; &lt;orth extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἀγκαλιδη-φόρος&lt;/orth&gt;, &lt;orth extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἀγκᾰλῐδη-φορέω&lt;/orth&gt; being used of men, &lt;bibl n=&quot;Perseus:abo:tlg,0542,001:2:139&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Poll.&lt;/author&gt; 2.139&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0542,001:7:109&quot; default=&quot;NO&quot;&gt;7.109&lt;/bibl&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n541\" data-lsj-ordinal=\"545\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκαλίδη\" data-meanings=\"Substantivo feminino: equivalente a ἀγκαλίς, braçada, colo; de uma mulher, inscrição de Amiso, Studia Pontica 3.6.\">ἀγκαλίδη</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo feminino: equivalente a ἀγκαλίς, braçada, colo; de uma mulher, inscrição de Amiso, Studia Pontica 3.6.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p></p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gkali/dh&quot; orig_id=&quot;n541&quot; key=&quot;a)gkali/dh&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκαλίδη&quot;&gt;ἀγκαλίδη&lt;/head&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἡ&lt;/gen&gt;, &lt;sense id=&quot;n541.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;= ἀγκαλίς, ἐν ἀγκαλίδῃσι γυναικός &lt;title&gt;Stud.Pont.&lt;/title&gt; 3.6 (&lt;placeName&gt;Amisus&lt;/placeName&gt;).&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n542\" data-lsj-ordinal=\"546\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκαλίζομαι\" data-meanings=\"Verbo médio: abraçar, tomar nos braços, cercar de carinho, até de algo mau; Semônides, Antologia Palatina e Licófron; particípio passivo ἀγκαλιζό\">ἀγκαλίζομαι</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Verbo médio: abraçar, tomar nos braços, cercar de carinho, até de algo mau; Semônides, Antologia Palatina e Licófron; particípio passivo ἀγκαλιζόμενος em Esopo.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Semon. 7.77 · AP 12.122 · Man. 1.45 · Lyc. 142 · Aesop. 366</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gka^li/zomai&quot; orig_id=&quot;n542&quot; key=&quot;a)gka^li/zomai&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;full&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκᾰλ-ίζομαι&quot;&gt;ἀγκαλίζομαι&lt;/head&gt;, &lt;sense id=&quot;n542.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;embrace,&lt;/i&gt; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ὅστις κακὸν ἀγκαλίζεται&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0260,001:7:77&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Semon.&lt;/author&gt; 7.77&lt;/bibl&gt;&lt;/cit&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;εἰς τρυΦερὰς ἠγκαλίσασθε χέρας&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,7000,001:12:122&quot; default=&quot;NO&quot;&gt;&lt;title&gt;AP&lt;/title&gt; 12.122&lt;/bibl&gt;&lt;/cit&gt; (&lt;author&gt;Mel.&lt;/author&gt;), cf. &lt;bibl n=&quot;Perseus:abo:tlg,2583,001:1:45&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Man.&lt;/author&gt; 1.45&lt;/bibl&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;χεροῖν εἴδωλον ἠγκαλισμένος&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0341,002:142&quot;&gt;&lt;author&gt;Lyc.&lt;/author&gt; 142&lt;/bibl&gt;&lt;/cit&gt;: &lt;foreign lang=&quot;grc&quot;&gt;ἀγκαλιζόμενος&lt;/foreign&gt; in pass. sense, &lt;bibl n=&quot;Perseus:abo:tlg,0096,002:366&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Aesop.&lt;/author&gt; 366&lt;/bibl&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n543\" data-lsj-ordinal=\"547\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκαλῖναι\" data-meanings=\"Feminino plural: braços, abraço, colo; forma argiva equivalente a ἀγκάλαι, Hesíquio.\">ἀγκαλῖναι</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Feminino plural: braços, abraço, colo; forma argiva equivalente a ἀγκάλαι, Hesíquio.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p></p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gka^li=nai&quot; orig_id=&quot;n543&quot; key=&quot;a)gka^li=nai&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκᾰλ-ῖναι&quot;&gt;ἀγκαλῖναι&lt;/head&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;αἱ&lt;/gen&gt;, &lt;sense id=&quot;n543.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;= ἀγκάλαι (Arg.), &lt;author&gt;Hsch.&lt;/author&gt;&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n544\" data-lsj-ordinal=\"548\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκαλίς\" data-meanings=\"Substantivo feminino. I. No plural, braços, colo, também dativo plural épico ἀγκαλίδεσσιν; Ilíada e inscrições. II. Braçada de objetos, quantidad\">ἀγκαλίς</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo feminino. I. No plural, braços, colo, também dativo plural épico ἀγκαλίδεσσιν; Ilíada e inscrições. II. Braçada de objetos, quantidade que os braços podem conter; Aristófanes, Plutarco. III. Na Macedônia, δρέπανον, foice, segundo Josefo e Hesíquio.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Il. 18.555 · 22.503 · Ar. Fr. 418 · Nicostr. 24 · Ister 54 · Ph. 5.147C. · Plu. Rom. 8 · J. AJ 5.1.2</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gka^li/s&quot; orig_id=&quot;n544&quot; key=&quot;a)gka^li/s&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκᾰλ-ίς&quot;&gt;ἀγκαλίς&lt;/head&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ἡ&lt;/gen&gt;, in pl., &lt;sense id=&quot;n544.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;= ἀγκάλαι, &lt;i&gt;arms,&lt;/i&gt; &lt;gramGrp opt=&quot;n&quot;&gt;&lt;gram type=&quot;dialect&quot; opt=&quot;n&quot;&gt;Ep.&lt;/gram&gt;&lt;/gramGrp&gt; dat. pl. &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ἀγκαλίδεσσιν&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0012,001:18:555&quot;&gt;&lt;title&gt;Il.&lt;/title&gt; 18.555&lt;/bibl&gt;&lt;/cit&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0012,001:22:503&quot;&gt;22.503&lt;/bibl&gt;; &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ὑπʼ ἀγκαλίσιν&lt;/quote&gt; &lt;title&gt;IG&lt;/title&gt; 9(1).882.13&lt;/cit&gt; (&lt;placeName&gt;Corcyra&lt;/placeName&gt;). &lt;/sense&gt;&lt;sense n=&quot;2&quot; id=&quot;n544.1&quot; level=&quot;3&quot; opt=&quot;n&quot;&gt; &lt;i&gt;armful,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0019,012:418&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Ar.&lt;/author&gt; &lt;title&gt;Fr.&lt;/title&gt; 418&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,2037,001:24&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Nicostr.&lt;/author&gt; 24&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,1450,001:54&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Ister&lt;/author&gt; 54&lt;/bibl&gt; (s. v. l.), &lt;bibl n=&quot;Perseus:abo:tlg,0018,001:5:147C&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Ph.&lt;/author&gt; 5.147C.&lt;/bibl&gt;, &lt;bibl n=&quot;Perseus:abo:tlg,0007,002:8&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Plu.&lt;/author&gt; &lt;title&gt;Rom.&lt;/title&gt; 8&lt;/bibl&gt;. &lt;/sense&gt;&lt;sense n=&quot;II&quot; id=&quot;n544.2&quot; level=&quot;2&quot; opt=&quot;n&quot;&gt; = δρέπανον, Maced. word, &lt;bibl n=&quot;Perseus:abo:tlg,0526,001:5:1:2&quot;&gt;&lt;author&gt;J.&lt;/author&gt; &lt;title&gt;AJ&lt;/title&gt; 5.1.2&lt;/bibl&gt;, &lt;author&gt;Hsch.&lt;/author&gt;&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n545\" data-lsj-ordinal=\"549\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκάλισμα\" data-meanings=\"Substantivo neutro, genitivo -ατος. I. Aquilo que se toma nos braços, objeto abraçado; por extensão, pessoa querida, predileta, Luciano e Licófro\">ἀγκάλισμα</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo neutro, genitivo -ατος. I. Aquilo que se toma nos braços, objeto abraçado; por extensão, pessoa querida, predileta, Luciano e Licófron. II. Abraço, figuradamente das brisas; Timóteo, Persas 91.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p>Luc. Am. 14 · Lyc. 308 · Tim. Pers. 91</p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gka^/lisma&quot; orig_id=&quot;n545&quot; key=&quot;a)gka^/lisma&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκᾰλ-ισμα&quot;&gt;ἀγκάλισμα&lt;/head&gt;, &lt;itype lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ατος&lt;/itype&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;τό&lt;/gen&gt;, &lt;sense id=&quot;n545.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;that which is embraced&lt;/i&gt; or &lt;i&gt;taken in the arms,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0061,002:14&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Luc.&lt;/author&gt; &lt;title&gt;Am.&lt;/title&gt; 14&lt;/bibl&gt;: hence, &lt;i&gt;darling,&lt;/i&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0341,002:308&quot;&gt;&lt;author&gt;Lyc.&lt;/author&gt; 308&lt;/bibl&gt;. &lt;/sense&gt;&lt;sense n=&quot;II&quot; id=&quot;n545.1&quot; level=&quot;2&quot; opt=&quot;n&quot;&gt; &lt;i&gt;embrace,&lt;/i&gt; metaph., &lt;cit&gt;&lt;quote lang=&quot;grc&quot;&gt;ἀ. κλυσιδρομάδος αὔρας&lt;/quote&gt; &lt;bibl n=&quot;Perseus:abo:tlg,0376,001:91&quot; default=&quot;NO&quot;&gt;&lt;author&gt;Tim.&lt;/author&gt; &lt;title&gt;Pers.&lt;/title&gt; 91&lt;/bibl&gt;&lt;/cit&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n<article id=\"entry-lsj-n546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n546\" data-lsj-ordinal=\"550\" hidden><h1 class=\"entry-title greek tooltip-trigger\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγκαλισμός\" data-meanings=\"Substantivo masculino: operação de reunir em braçadas ou formar feixes; papiro de Oxirrinco 1631.9, século III d.C.\">ἀγκαλισμός</h1><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\">Substantivo masculino: operação de reunir em braçadas ou formar feixes; papiro de Oxirrinco 1631.9, século III d.C.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências da fonte</div><p></p></section><details><summary>Fonte TEI integral para cotejo</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">&lt;div2 id=&quot;crossa)gka^lismo/s&quot; orig_id=&quot;n546&quot; key=&quot;a)gka^lismo/s&quot; type=&quot;main&quot; opt=&quot;n&quot;&gt;&lt;head extent=&quot;suff&quot; lang=&quot;grc&quot; opt=&quot;n&quot; orth_orig=&quot;ἀγκᾰλ-ισμός&quot;&gt;ἀγκαλισμός&lt;/head&gt;, &lt;gen lang=&quot;grc&quot; opt=&quot;n&quot;&gt;ὁ&lt;/gen&gt;, &lt;sense id=&quot;n546.0&quot; n=&quot;&quot; level=&quot;1&quot; opt=&quot;n&quot;&gt;&lt;i&gt;making&lt;/i&gt;  &lt;i&gt;into bundles,&lt;/i&gt; &lt;title&gt;POxy.&lt;/title&gt; 1631.9 &lt;date&gt;(iii A.D.)&lt;/date&gt;.&lt;/sense&gt;&lt;/div2&gt;</pre></details></article>\n";
